-- Disposable PostgreSQL 17 database only; no production data or bank connection.
DO $cases$
DECLARE u constant uuid:='00000000-0000-4000-8000-000000000001';other_u constant uuid:='00000000-0000-4000-8000-000000000002';
 previous_id constant uuid:='00000000-0000-4000-8000-000000000010';next_id constant uuid:='00000000-0000-4000-8000-000000000011';
 cases constant jsonb:=$fixture_cases$[{"id":"previous_bill_settled_by_next_bill","status":"paid","reported":100,"count":2},{"id":"observed_other_payment_keeps_all_cycle_guards","next_r":{"payments":[{"id":"payment-a","amount":100,"valueType":"OTHER_PAYMENT","paymentDate":"2026-09-20T00:00:00Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"}]},"status":"paid","reported":100,"count":2},{"id":"partial_payment_is_not_settlement","next_r":{"payments":[{"id":"payment-a","amount":50,"valueType":"PARTIAL_PAYMENT","paymentDate":"2026-09-20T00:00:00Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"}]},"status":"payment_reported","reported":50,"count":2},{"id":"payment_on_current_bill_does_not_settle_itself","previous_r":{"payments":[{"id":"payment-a","amount":100,"valueType":"FULL_PAYMENT","paymentDate":"2026-09-20T00:00:00Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"}]},"next_r":{"payments":[]},"status":"payment_not_reported","reported":0,"count":2},{"id":"payment_after_next_closing_is_outside_cycle","next_r":{"payments":[{"id":"payment-a","amount":100,"valueType":"FULL_PAYMENT","paymentDate":"2026-10-20T00:00:00Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"}]},"status":"payment_not_reported","reported":0,"count":2},{"id":"payment_before_prior_closing_is_outside_cycle","next_r":{"payments":[{"id":"payment-a","amount":100,"valueType":"FULL_PAYMENT","paymentDate":"2026-09-01","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"}]},"status":"payment_not_reported","reported":0,"count":2},{"id":"charges_require_exact_additional_payment","next_r":{"payments":[{"id":"payment-a","amount":110,"valueType":"FULL_PAYMENT","paymentDate":"2026-09-20T00:00:00Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"}],"financeCharges":[{"id":"fee-a","amount":10,"currencyCode":"BRL"}]},"status":"paid","reported":110,"count":2},{"id":"uncovered_charges_are_not_paid","next_r":{"financeCharges":[{"id":"fee-a","amount":10,"currencyCode":"BRL"}]},"status":"payment_reported","reported":100,"count":2},{"id":"invalid_payment_beside_valid_one_taints_settlement","next_r":{"payments":[{"id":"payment-a","amount":100,"valueType":"FULL_PAYMENT","paymentDate":"2026-09-20T00:00:00Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"},{"id":"","amount":25,"valueType":"FULL_PAYMENT","paymentDate":"2026-09-20T00:00:00Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"}]},"status":"payment_reported","reported":100,"count":2},{"id":"invalid_calendar_is_not_a_reader_crash","next_r":{"payments":[{"id":"payment-a","amount":100,"valueType":"FULL_PAYMENT","paymentDate":"2026-09-20T00:00:00Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"},{"id":"payment-b","amount":100,"valueType":"FULL_PAYMENT","paymentDate":"2026-02-31","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"}]},"status":"payment_reported","reported":100,"count":2},{"id":"invalid_payment_timestamp_is_not_a_proof","next_r":{"payments":[{"id":"payment-a","amount":100,"valueType":"FULL_PAYMENT","paymentDate":"2026-09-20T99:00:00Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"}]},"status":"payment_reported","reported":100,"count":2},{"id":"identical_payment_retry_counts_once","next_r":{"payments":[{"id":"payment-a","amount":100,"valueType":"FULL_PAYMENT","paymentDate":"2026-09-20T00:00:00Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"},{"id":"payment-a","amount":100,"valueType":"FULL_PAYMENT","paymentDate":"2026-09-20T00:00:00Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"}]},"status":"paid","reported":100,"count":2},{"id":"conflicting_payment_id_is_not_accepted","next_r":{"payments":[{"id":"payment-a","amount":100,"valueType":"FULL_PAYMENT","paymentDate":"2026-09-20T00:00:00Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"},{"id":"payment-a","amount":120,"valueType":"FULL_PAYMENT","paymentDate":"2026-09-20T00:00:00Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"}]},"status":"payment_not_reported","reported":0,"count":2},{"id":"duplicate_fee_id_cannot_prove_settlement","next_r":{"payments":[{"id":"payment-a","amount":120,"valueType":"FULL_PAYMENT","paymentDate":"2026-09-20T00:00:00Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"}],"financeCharges":[{"id":"fee-a","amount":10,"currencyCode":"BRL"},{"id":"fee-a","amount":10,"currencyCode":"BRL"}]},"status":"payment_reported","reported":120,"count":2},{"id":"malformed_payment_array_is_not_a_crash","next_r":{"payments":{}},"status":"payment_not_reported","reported":0,"count":2},{"id":"unknown_payment_type_is_not_accepted","next_r":{"payments":[{"id":"payment-a","amount":100,"valueType":"UNKNOWN","paymentDate":"2026-09-20T00:00:00Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"}]},"status":"payment_not_reported","reported":0,"count":2},{"id":"foreign_currency_cannot_settle_brl_bill","next_r":{"payments":[{"id":"payment-a","amount":100,"valueType":"FULL_PAYMENT","paymentDate":"2026-09-20T00:00:00Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"USD"}]},"status":"payment_not_reported","reported":0,"count":2},{"id":"nonfinite_payment_is_not_accepted","next_r":{"payments":[{"id":"payment-a","amount":"NaN","valueType":"FULL_PAYMENT","paymentDate":"2026-09-20T00:00:00Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"}]},"status":"payment_not_reported","reported":0,"count":2},{"id":"malformed_warnings_do_not_crash_reader","next_n":{"warnings":{}},"status":"payment_not_reported","reported":0,"count":1},{"id":"explicit_warning_blocks_invoice_evidence","next_n":{"warnings":["uncertain"]},"status":"payment_not_reported","reported":0,"count":1},{"id":"impossible_issuer_due_does_not_use_fallback","next_n":{"due_date":"2026-02-31"},"status":"payment_not_reported","reported":0,"count":1},{"id":"impossible_closing_is_not_a_reader_crash","next_n":{"closing_date":"2026-02-31"},"status":"payment_not_reported","reported":0,"count":1},{"id":"invalid_revision_timezone_blocks_source","next_n":{"provider_updated_at":"2026-10-16T00:00:00"},"status":"payment_not_reported","reported":0,"count":1},{"id":"collection_clock_is_not_an_issuer_revision","delete_next_n":["provider_updated_at"],"delete_next_r":["updatedAt"],"next_n":{"source_sync_at":"2026-10-17T23:59:59Z"},"status":"payment_not_reported","reported":0,"count":1},{"id":"deleted_next_invoice_not_revived","delete_next":true,"status":"payment_not_reported","reported":0,"count":1},{"id":"other_source_account_does_not_settle_bill","next_account":"foreign-account","status":"payment_not_reported","reported":0,"count":1},{"id":"credit_card_owned_by_another_user_cannot_authorize_invoice","card_other_owner":true,"status":null,"count":0},{"id":"invoice_owned_by_another_user_is_not_returned","previous_other_owner":true,"status":null,"count":1},{"id":"ambiguous_adjacent_cycle_not_accepted","duplicate_next":true,"status":"payment_not_reported","reported":0,"count":1},{"id":"nonfinite_invoice_amount_is_rejected","next_amount":"NaN","status":"payment_not_reported","reported":0,"count":1},{"id":"negative_invoice_amount_is_rejected","next_amount":"-1","status":"payment_not_reported","reported":0,"count":1},{"id":"null_owner_has_no_invoices","query_null_owner":true,"status":null,"count":0}]$fixture_cases$::jsonb;
 base_payment constant jsonb:=$payment${"id":"payment-a","amount":100,"valueType":"FULL_PAYMENT","paymentDate":"2026-09-20T00:00:00Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"}$payment$::jsonb;
 c jsonb;pn jsonb;nn jsonb;pr jsonb;nr jsonb;k text;v record;rows_returned integer;checked integer:=0;
BEGIN
 IF current_database()<>'lts_bill_source_qa' THEN RAISE EXCEPTION 'Dedicated disposable QA database required';END IF;
 IF current_date<date '2026-10-12' THEN RAISE EXCEPTION 'Fixture payments require clock at or after 2026-10-12';END IF;
 FOR c IN SELECT value FROM jsonb_array_elements(cases) LOOP
  TRUNCATE public.lts_open_finance_staging;
  pn:='{"due_date":"2026-09-20","closing_date":"2026-09-09","provider_updated_at":"2026-10-16T18:00:00Z","warnings":[],"card_name":"Fixture Card","last4":"0001"}'::jsonb||coalesce(c->'previous_n','{}'::jsonb);
  nn:='{"due_date":"2026-10-20","closing_date":"2026-10-09","provider_updated_at":"2026-10-16T18:00:00Z","warnings":[],"card_name":"Fixture Card","last4":"0001"}'::jsonb||coalesce(c->'next_n','{}'::jsonb);
  pr:='{"updatedAt":"2026-10-16T18:00:00Z","payments":[],"financeCharges":[]}'::jsonb||coalesce(c->'previous_r','{}'::jsonb);
  nr:=jsonb_build_object('updatedAt','2026-10-16T18:00:00Z','payments',jsonb_build_array(base_payment),'financeCharges','[]'::jsonb)||coalesce(c->'next_r','{}'::jsonb);
  FOR k IN SELECT jsonb_array_elements_text(coalesce(c->'delete_next_n','[]'::jsonb)) LOOP nn:=nn-k;END LOOP;
  FOR k IN SELECT jsonb_array_elements_text(coalesce(c->'delete_next_r','[]'::jsonb)) LOOP nr:=nr-k;END LOOP;
  INSERT INTO public.lts_open_finance_staging(id,user_id,resource_type,provider_account_ref,institution_name,institution_code,normalized_payload,raw_payload,currency,signed_amount,last_seen_at)
  VALUES('00000000-0000-4000-8000-000000000003',CASE WHEN coalesce((c->>'card_other_owner')::boolean,false) THEN other_u ELSE u END,'credit_card','account-qa','Fixture Bank','QA',
   '{"name":"Fixture Card","provider_account_id":"account-qa"}','{}','BRL',0,'2026-10-17T00:00:00Z'),
   ('00000000-0000-4000-8000-000000000004',u,'card_transaction','account-qa','Fixture Bank','QA','{}','{}','BRL',-100,'2026-10-17T00:00:00Z');
  INSERT INTO public.lts_open_finance_staging(id,user_id,resource_type,provider_record_id,provider_account_ref,institution_name,institution_code,normalized_payload,raw_payload,currency,signed_amount,posting_date,last_seen_at,provider_deleted_at)
  VALUES(previous_id,CASE WHEN coalesce((c->>'previous_other_owner')::boolean,false) THEN other_u ELSE u END,'invoice','bill-previous','account-qa','Fixture Bank','QA',pn,pr,'BRL',100,'2026-09-20','2026-10-17T00:00:00Z',NULL),
   (next_id,u,'invoice','bill-next',coalesce(c->>'next_account','account-qa'),'Fixture Bank','QA',nn,nr,'BRL',coalesce(c->>'next_amount','200')::numeric,'2026-10-20','2026-10-17T00:00:00Z',
    CASE WHEN coalesce((c->>'delete_next')::boolean,false) THEN '2026-10-17T00:00:00Z'::timestamptz END);
  IF coalesce((c->>'duplicate_next')::boolean,false) THEN
   INSERT INTO public.lts_open_finance_staging SELECT
    '00000000-0000-4000-8000-000000000012'::uuid,user_id,resource_type,'competing-bill',provider_account_ref,raw_payload,normalized_payload,posting_date,institution_name,institution_code,provider_deleted_at,currency,signed_amount,last_seen_at,created_at
    FROM public.lts_open_finance_staging WHERE id=next_id;
  END IF;
  SELECT count(*) INTO rows_returned FROM public.lts_current_received_card_bills_v263(CASE WHEN coalesce((c->>'query_null_owner')::boolean,false) THEN NULL::uuid ELSE u END);
  IF rows_returned<>(c->>'count')::integer THEN RAISE EXCEPTION 'Case %: expected % rows, got %',c->>'id',c->>'count',rows_returned;END IF;
  SELECT * INTO v FROM public.lts_current_received_card_bills_v263(CASE WHEN coalesce((c->>'query_null_owner')::boolean,false) THEN NULL::uuid ELSE u END) WHERE invoice_source_id=previous_id;
  IF v.payment_status IS DISTINCT FROM c->>'status' THEN RAISE EXCEPTION 'Case %: expected status %, got %',c->>'id',c->>'status',v.payment_status;END IF;
  IF c ? 'reported' AND v.reported_payment_amount IS DISTINCT FROM (c->>'reported')::numeric THEN RAISE EXCEPTION 'Case %: expected reported %, got %',c->>'id',c->>'reported',v.reported_payment_amount;END IF;
  checked:=checked+1;
 END LOOP;
 PERFORM set_config('lts.received_reader_unit',jsonb_build_object('pass',true,'cases',checked,'real_received_reader',true,'data','synthetic_disposable_database_only')::text,true);
END $cases$;
SELECT current_setting('lts.received_reader_unit')::jsonb AS result;
